/**
 * Tasks API client.
 *
 * Thin typed wrappers over the Tier-2 task endpoints shipped in T11/T13:
 *   * `GET    /api/v1/tasks`              (list, paginated + filtered)
 *   * `GET    /api/v1/tasks/{task_id}`    (single)
 *   * `POST   /api/v1/tasks/{task_id}/cancel`
 *   * `POST   /api/v1/workflows/{wf_id}/batch` (batch submit, T10)
 *
 * Why hand-rolled types: the generated `schema.d.ts` is regenerated by
 * `pnpm codegen:api:offline`, which needs the API server up to snapshot
 * OpenAPI. The list + stream + batch endpoints landed in T10/T13 after
 * the last codegen pass, so the typed paths aren't there yet. Mirroring
 * the contract here keeps T14 unblocked; a follow-up codegen run will
 * tighten this back to `apiClient.GET(...)`-style calls.
 *
 * All requests funnel through the same `apiClient` so they pick up the
 * auth `Authorization` header + 401 handling for free.
 */
import { apiClient } from '@/lib/api/client';
import { getApiBase } from '@/lib/base-path';
import type {
  ResourceAccess,
  ResourceProvenance,
} from '@/lib/api/organizations';

// ---------------------------------------------------------------------------
// Contract — kept in sync with `routes/tasks.py::_task_to_out` and the
// `ck_tasks_status` CHECK constraint in `models_tasks.py`.
// ---------------------------------------------------------------------------

export type TaskStatus =
  | 'queued'
  | 'running'
  | 'resuming'
  | 'finished'
  | 'finished_with_errors'
  | 'failed'
  | 'interrupted'
  | 'cancelling'
  | 'cancelled'
  | 'enabled'
  | 'paused';

export type TaskType = 'batch_exec' | 'scheduled_run';

export interface Task {
  id: string;
  status: TaskStatus;
  /** Progress in [0, 1]. `0` for queued tasks, `1` for finished. */
  progress: number;
  task_type: TaskType;
  workflow_id: string | null;
  payload: unknown;
  result: unknown;
  results_uri: string | null;
  error: string | null;
  background_job_id: string | null;
  sandbox_status?: TaskSandboxStatus | null;
  submitted_at: string;
  started_at: string | null;
  finished_at: string | null;
  access: ResourceAccess;
  provenance: ResourceProvenance;
}

export type TaskSandboxStatus =
  | 'pending'
  | 'starting'
  | 'running'
  | 'releasing'
  | 'released'
  | 'lost'
  | 'failed_to_start';

export type TaskEventType = 'state' | 'progress' | 'log' | 'result' | 'terminal';

export interface TaskEventPayload {
  schema_version?: number;
  _event_ts?: string;
  level?: 'debug' | 'info' | 'warning' | 'error' | string;
  category?: string;
  action?: string;
  message?: string;
  task_status?: TaskStatus | string;
  sandbox_status?: TaskSandboxStatus | string;
  scope?: { type?: string; id?: string | null; name?: string | null } | null;
  progress?: {
    done?: number;
    total?: number;
    unit?: string;
    percent?: number;
  } | null;
  data?: unknown;
  error?: {
    code?: string;
    message?: string;
    retryable?: boolean;
    details?: unknown;
  } | null;
}

export interface TaskEvent {
  id: number;
  task_id: string;
  ts: string | null;
  event_type: TaskEventType;
  payload: TaskEventPayload;
}

