// ---------------------------------------------------------------------------
// Internal: thin fetch helper that reuses the same base URL + auth header
// pipeline the typed `apiClient` uses. `openapi-fetch` exposes the underlying
// `fetch` it composed via `apiClient.GET / POST` — we go one layer below for
// the un-codegenned routes so we still pick up the auth middleware.
// ---------------------------------------------------------------------------

const BASE = getApiBase();

/**
 * Mirror the `Authorization` + 401 middleware behaviour of `apiClient`
 * for paths that aren't yet in `schema.d.ts`. We import the auth store
 * lazily to avoid a circular import in tests.
 */
async function authedFetch(
  path: string,
  init: RequestInit = {},
): Promise<Response> {
  const { useAuthStore } = await import('@/stores/auth');
  const token = useAuthStore.getState().token;
  const headers = new Headers(init.headers);
  if (token) headers.set('Authorization', `Bearer ${token}`);
  if (init.body && !headers.has('Content-Type')) {
    headers.set('Content-Type', 'application/json');
  }
  const resp = await fetch(`${BASE}${path}`, { ...init, headers });
  if (resp.status === 401) {
    useAuthStore.getState().handle401();
  }
  return resp;
}

function buildListQuery(p: ListTasksParams): string {
  const params = new URLSearchParams();
  for (const s of p.status ?? []) params.append('status', s);
  for (const t of p.task_type ?? []) params.append('task_type', t);
  if (p.workflow_id) params.set('workflow_id', p.workflow_id);
  if (p.q) params.set('q', p.q);
  if (p.limit !== undefined) params.set('limit', String(p.limit));
  if (p.offset !== undefined) params.set('offset', String(p.offset));
  const qs = params.toString();
  return qs ? `?${qs}` : '';
}

// ---------------------------------------------------------------------------
// Public API.
// ---------------------------------------------------------------------------

export async function listTasks(
  params: ListTasksParams = {},
): Promise<TaskListResponse> {
  const resp = await authedFetch(`/api/v1/tasks${buildListQuery(params)}`);
  if (!resp.ok) {
    throw new Error(`listTasks failed: ${resp.status} ${resp.statusText}`);
  }
  return (await resp.json()) as TaskListResponse;
}

export async function getTaskSummary(params: { task_type?: TaskType[] } = {}): Promise<TaskSummary> {
  const query = new URLSearchParams();
  for (const type of params.task_type ?? []) query.append('task_type', type);
  const suffix = query.toString() ? `?${query.toString()}` : '';
  const resp = await authedFetch(`/api/v1/tasks/summary${suffix}`);
  if (!resp.ok) {
    throw new Error(`getTaskSummary failed: ${resp.status} ${resp.statusText}`);
  }
  return (await resp.json()) as TaskSummary;
}

export async function getTask(id: string): Promise<Task> {
  // Use the codegenned client for the single-task GET since the schema
  // already has it — keeps the existing 401 middleware in play.
  const { data, error } = await apiClient.GET(
    '/api/v1/tasks/{task_id}',
    { params: { path: { task_id: id } } },
  );
  if (error) throw error;
  return data as unknown as Task;
}

export async function cancelTask(
  id: string,
  mode: CancelMode = 'soft',
): Promise<{ status: string }> {
  const resp = await authedFetch(`/api/v1/tasks/${id}/cancel`, {
    method: 'POST',
    body: JSON.stringify({ mode }),
  });
  if (!resp.ok) {
    throw new Error(`cancelTask failed: ${resp.status} ${resp.statusText}`);
  }
  return (await resp.json()) as { status: string };
}

