export async function getTaskEvents(
  id: string,
  params: {
    after_seq?: number;
    before_seq?: number;
    event_type?: TaskEventType[];
    limit?: number;
    from?: string;
    to?: string;
    order?: 'asc' | 'desc';
  } = {},
): Promise<TaskEventsResponse> {
  const qs = new URLSearchParams();
  if (params.after_seq !== undefined) qs.set('after_seq', String(params.after_seq));
  if (params.before_seq !== undefined) qs.set('before_seq', String(params.before_seq));
  for (const t of params.event_type ?? []) qs.append('event_type', t);
  if (params.limit !== undefined) qs.set('limit', String(params.limit));
  if (params.from) qs.set('from', params.from);
  if (params.to) qs.set('to', params.to);
  if (params.order) qs.set('order', params.order);
  const query = qs.toString();
  const resp = await authedFetch(`/api/v1/tasks/${id}/events${query ? `?${query}` : ''}`);
  if (!resp.ok) {
    throw new Error(`getTaskEvents failed: ${resp.status} ${resp.statusText}`);
  }
  return (await resp.json()) as TaskEventsResponse;
}

/** Where the aggregated results table is written. v1: a durable /data VFS path.
 *  The `type` is the destination kind (future: cloud sheets) — see the backend
 *  BatchOutputSink abstraction. Omit `output` to keep results only in the task's
 *  downloadable copy. */
export interface BatchOutputSpec {
  type: 'vfs_data';
  path: string;
  /** The sheet to write into when `path` is an Excel file (.xlsx/.xls). */
  sheet_name?: string;
}

/**
 * One column of the batch output table. The output table is EXACTLY these
 * columns, in array order (left-to-right). `index`/`status`/`error`/
 * `execution_time` are fixed per-row metadata columns; `field` pulls a value
 * from a node's output (`node`.`field`), with an optional `default` substituted
 * when the run produced no value. `default` is omitted from the wire when blank.
 */
export type BatchOutputColumn =
  | { kind: 'index'; name: string }
  | { kind: 'status'; name: string }
  | { kind: 'execution_time'; name: string }
  | { kind: 'error'; name: string }
  | { kind: 'field'; name: string; node: string; field: string; default?: string };

export interface SubmitBatchBody {
  data_source: unknown;
  column_mapping: Record<string, string>;
  output?: BatchOutputSpec | null;
  /** How many rows run in parallel (thread pool, clamped 1..16 server-side). */
  concurrency?: number;
  /** The exact, ordered output-table columns. Omitted → server default shape. */
  output_columns?: BatchOutputColumn[];
}

export async function submitBatch(
  wfId: string,
  body: SubmitBatchBody,
): Promise<{ task_id: string }> {
  const resp = await authedFetch(`/api/v1/workflows/${wfId}/batch`, {
    method: 'POST',
    body: JSON.stringify(body),
  });
  if (!resp.ok) {
    throw new Error(`submitBatch failed: ${resp.status} ${resp.statusText}`);
  }
  return (await resp.json()) as { task_id: string };
}
